BEGIN;

UPDATE public.grammar_rules
SET content = '{"analogy_en":"Think of the subordinate clause as a ''verb prison.'' When a subordinating conjunction appears, it locks the verb at the end of its clause. The verb can''t escape until the clause ends!","paragraphs_en":["Subordinating conjunctions connect a main clause to a subordinate (dependent) clause. The subordinate clause cannot stand alone — it depends on the main clause for meaning.","The key rule: In a subordinate clause, the conjugated verb goes to the end. ''Ich weiß, dass er heute kommt'' — ''kommt'' is kicked to the final position.","Common subordinating conjunctions include: dass (that), weil (because), wenn (when/if), ob (whether/if)."],"native_perspective_en":"Germans expect the verb at the end after these conjunctions. ''Ich weiß, dass er kommt heute'' sounds completely wrong — ''heute'' must come before the verb."}'::jsonb
WHERE id = '0f26a534-ac51-44b5-b0a6-3fc3c3e2b24e'::uuid
  AND content = '{"analogy_en":"Think of the subordinate clause as a ''verb prison.'' When a subordinating conjunction appears, it locks the verb at the end of its clause. The verb can''t escape until the clause ends!","paragraphs_en":["Subordinating conjunctions connect a main clause to a subordinate (dependent) clause. The subordinate clause cannot stand alone — it depends on the main clause for meaning.","The key rule: In a subordinate clause, the conjugated verb goes to the end. ''Ich weiß, dass er heute kommt'' — ''kommt'' is kicked to the final position.","Common subordinating conjunctions include: dass (that), weil (because), wenn (when/if), ob (whether/if), obwohl (although), während (while), bevor (before), nachdem (after), bis (until), seit/seitdem (since)."],"native_perspective_en":"Germans expect the verb at the end after these conjunctions. ''Ich weiß, dass er kommt heute'' sounds completely wrong — ''heute'' must come before the verb."}'::jsonb;

UPDATE public.grammar_rules
SET content = '{"intro_en":"These conjunctions all send the verb to the end of their clause:","conjunctions":[{"use":"Statements, opinions, reported speech","meaning":"that","example_de":"Ich weiß, dass er krank ist.","example_en":"I know that he is sick.","conjunction":"dass"},{"use":"Giving reasons","meaning":"because","example_de":"Ich bleibe, weil es regnet.","example_en":"I stay because it is raining.","conjunction":"weil"},{"use":"Conditions, repeated events","meaning":"when, if, whenever","example_de":"Wenn es regnet, bleibe ich zu Hause.","example_en":"When/If it rains, I stay home.","conjunction":"wenn"},{"use":"Indirect yes/no questions","meaning":"whether, if (in questions)","example_de":"Ich weiß nicht, ob er kommt.","example_en":"I don''t know whether he is coming.","conjunction":"ob"}],"key_point_en":"ALL of these send the verb to the end. No exceptions!"}'::jsonb
WHERE id = '5a22ce56-ce50-40b1-85cc-870c1418feb5'::uuid
  AND content = '{"intro_en":"These conjunctions all send the verb to the end of their clause:","conjunctions":[{"use":"Statements, opinions, reported speech","meaning":"that","example_de":"Ich weiß, dass er krank ist.","example_en":"I know that he is sick.","conjunction":"dass"},{"use":"Giving reasons","meaning":"because","example_de":"Ich bleibe, weil es regnet.","example_en":"I stay because it is raining.","conjunction":"weil"},{"use":"Conditions, repeated events","meaning":"when, if, whenever","example_de":"Wenn es regnet, bleibe ich zu Hause.","example_en":"When/If it rains, I stay home.","conjunction":"wenn"},{"use":"Indirect yes/no questions","meaning":"whether, if (in questions)","example_de":"Ich weiß nicht, ob er kommt.","example_en":"I don''t know whether he is coming.","conjunction":"ob"},{"use":"Contrast, concession","meaning":"although, even though","example_de":"Ich gehe, obwohl ich müde bin.","example_en":"I go although I am tired.","conjunction":"obwohl"},{"use":"Simultaneous actions","meaning":"while, during","example_de":"Während ich koche, liest er.","example_en":"While I cook, he reads.","conjunction":"während"},{"use":"Sequence of events","meaning":"before","example_de":"Bevor ich gehe, esse ich.","example_en":"Before I go, I eat.","conjunction":"bevor"},{"use":"Sequence of events","meaning":"after","example_de":"Nachdem ich gegessen habe, gehe ich.","example_en":"After I have eaten, I go.","conjunction":"nachdem"},{"use":"Time limit","meaning":"until","example_de":"Warte, bis ich komme.","example_en":"Wait until I come.","conjunction":"bis"},{"use":"Starting point in time","meaning":"since (time)","example_de":"Seit ich hier wohne, bin ich glücklich.","example_en":"Since I live here, I am happy.","conjunction":"seit/seitdem"}],"key_point_en":"ALL of these send the verb to the end. No exceptions!"}'::jsonb;

