UPDATE public.grammar_rules
SET content = '{"speakers":["Anna","Ben"],"exchanges":[{"speaker":"Anna","text_de":"Kommst du heute Abend zur Party?","text_en":"Are you coming to the party tonight?","grammar_note":"Main clause, normal word order"},{"speaker":"Ben","text_de":"Ich weiß nicht, ob ich kommen kann.","text_en":"I don''t know whether I can come.","grammar_note":"ob + kommen kann (both verbs at end)"},{"speaker":"Anna","text_de":"Warum? Ich hoffe, dass du kommst!","text_en":"Why? I hope that you come!","grammar_note":"dass + kommst (verb at end)"},{"speaker":"Ben","text_de":"Weil ich morgen früh aufstehen muss.","text_en":"Because I have to get up early tomorrow.","grammar_note":"weil + aufstehen muss (infinitive + modal at end)"},{"speaker":"Anna","text_de":"Ich finde es schade, dass du nicht kommen kannst.","text_en":"I think it''s a shame that you can''t come.","grammar_note":"dass + kommen kannst (verb + modal at end)"},{"speaker":"Ben","text_de":"Wenn ich früher fertig bin, komme ich vielleicht doch.","text_en":"If I finish earlier, maybe I''ll come after all.","grammar_note":"Wenn-clause first: wenn ich fertig bin, komme ich..."}],"context_de":"Freunde besprechen Pläne und geben Gründe","context_en":"Friends discussing plans and giving reasons","grammar_focus_en":"Notice the verb position: ob ich kommen kann, dass du kommst, weil ich aufstehen muss, dass du nicht kommen kannst. Every subordinate clause has the verb at the end."}'::jsonb
WHERE id = '3b94a8ea-1f32-4b56-9f83-390fc56354d9'::uuid
  AND content = '{"speakers":["Anna","Ben"],"exchanges":[{"speaker":"Anna","text_de":"Kommst du heute Abend zur Party?","text_en":"Are you coming to the party tonight?","grammar_note":"Main clause, normal word order"},{"speaker":"Ben","text_de":"Ich weiß nicht, ob ich kommen kann.","text_en":"I don''t know whether I can come.","grammar_note":"ob + kommen kann (both verbs at end)"},{"speaker":"Anna","text_de":"Warum? Ich hoffe, dass du kommst!","text_en":"Why? I hope that you come!","grammar_note":"dass + kommst (verb at end)"},{"speaker":"Ben","text_de":"Weil ich morgen früh aufstehen muss.","text_en":"Because I have to get up early tomorrow.","grammar_note":"weil + aufstehen muss (infinitive + modal at end)"},{"speaker":"Anna","text_de":"Obwohl es schade ist, verstehe ich das.","text_en":"Although it''s a shame, I understand.","grammar_note":"obwohl + schade ist (verb at end)"},{"speaker":"Ben","text_de":"Wenn ich früher fertig bin, komme ich vielleicht doch.","text_en":"If I finish earlier, maybe I''ll come after all.","grammar_note":"Wenn-clause first: wenn ich fertig bin, komme ich..."}],"context_de":"Freunde besprechen Pläne und geben Gründe","context_en":"Friends discussing plans and giving reasons","grammar_focus_en":"Notice the verb position: ob ich kommen kann, dass du kommst, weil ich aufstehen muss, obwohl es schade ist. Every subordinate clause has the verb at the end."}'::jsonb;

