UPDATE public.grammar_rules
SET content = '{"sections":[{"title_en":"Main Clause vs. Subordinate Clause","content_de":"Im Hauptsatz steht das konjugierte Verb an Position 2.\nIm Nebensatz steht das konjugierte Verb am Ende.","content_en":"In main clauses (Hauptsatz), the conjugated verb is always in position 2:\n• Ich lerne jeden Tag Deutsch.\n• Er spielt gern Fußball.\n\nIn subordinate clauses (Nebensatz), the conjugated verb moves to the end:\n• Ich weiß, dass ich jeden Tag Deutsch lerne.\n• Er sagt, dass er gern Fußball spielt."},{"title_en":"What Triggers Verb-Final Order?","content_de":"Nebensatzkonjunktionen lösen Verbendstellung aus: dass, weil, wenn, ob.","content_en":"Subordinating conjunctions trigger verb-final order:\n• dass (that): Ich hoffe, dass du kommst.\n• weil (because): Ich bleibe, weil ich müde bin.\n• wenn (when/if): Wenn ich Zeit habe...\n• ob (whether): Ich weiß nicht, ob er kommt."}]}'::jsonb
WHERE id = '2c54936e-af66-4848-911b-9ab40645372b'::uuid
  AND content = '{"sections":[{"title_en":"Main Clause vs. Subordinate Clause","content_de":"Im Hauptsatz steht das konjugierte Verb an Position 2.\nIm Nebensatz steht das konjugierte Verb am Ende.","content_en":"In main clauses (Hauptsatz), the conjugated verb is always in position 2:\n• Ich lerne jeden Tag Deutsch.\n• Er spielt gern Fußball.\n\nIn subordinate clauses (Nebensatz), the conjugated verb moves to the end:\n• Ich weiß, dass ich jeden Tag Deutsch lerne.\n• Er sagt, dass er gern Fußball spielt."},{"title_en":"What Triggers Verb-Final Order?","content_de":"Nebensatzkonjunktionen lösen Verbendstellung aus: dass, weil, wenn, obwohl, ob, als, bevor, nachdem...","content_en":"Subordinating conjunctions trigger verb-final order:\n• dass (that): Ich hoffe, dass du kommst.\n• weil (because): Ich bleibe, weil ich müde bin.\n• Wenn (when/if): Wenn ich Zeit habe...\n• obwohl (although): Obwohl es regnet, gehe ich...\n• ob (whether): Ich weiß nicht, ob er kommt.\n• als (when - past): Als ich jung war...\n• bevor (before): Bevor du gehst...\n• nachdem (after): Nachdem er gegessen hat..."}]}'::jsonb;

UPDATE public.grammar_rules
SET content = '{"sections":[{"title_en":"Perfect Tense Order: Participle → haben/sein","content_de":"Das konjugierte Hilfsverb (habe/bin/hat/ist) steht ganz am Ende, nach dem Partizip.","content_en":"Main clause: Ich habe das Buch gelesen.\nSubordinate: ..., dass ich das Buch gelesen habe.\n\nMain clause: Er ist nach Berlin gefahren.\nSubordinate: ..., weil er nach Berlin gefahren ist.\n\nThe conjugated auxiliary (habe/bin/hat/ist) goes to the very end, after the participle."},{"title_en":"Modal Verbs in the Past","content_de":"Bei Modalverben in der Vergangenheit benutzt man oft das Präteritum: ...weil ich nicht kommen konnte.","content_en":"With modal verbs, the simple past (Präteritum) is common even in speech:\n\nMain: Ich konnte nicht kommen.\nSubordinate: ..., weil ich nicht kommen konnte.\n\nThe modal (konnte) goes to the very end, just like any other verb in a subordinate clause."}]}'::jsonb
WHERE id = 'e2b1fbba-75c2-426c-922c-94edd4ec1bd9'::uuid
  AND content = '{"sections":[{"title_en":"Perfect Tense Order: Participle → haben/sein","content_de":"Das konjugierte Hilfsverb (habe/bin/hat/ist) steht ganz am Ende, nach dem Partizip.","content_en":"Main clause: Ich habe das Buch gelesen.\nSubordinate: ..., dass ich das Buch gelesen habe.\n\nMain clause: Er ist nach Berlin gefahren.\nSubordinate: ..., weil er nach Berlin gefahren ist.\n\nThe conjugated auxiliary (habe/bin/hat/ist) goes to the very end, after the participle."},{"title_en":"Triple Stack: Modal + Perfect","content_de":"Mit Modalverben im Perfekt steht das Hilfsverb vor den Infinitiven: ...weil ich nicht habe kommen können.","content_en":"This gets tricky! With modal verbs in perfect tense:\n\nMain: Ich habe nicht kommen können.\nSubordinate: ..., weil ich nicht habe kommen können.\n\nWait — ''habe'' moved before the infinitives! This is the ''Ersatzinfinitiv'' rule: when modal + infinitive, the auxiliary goes before them."}]}'::jsonb;

UPDATE public.grammar_rules
SET content = '{"rows":[["dass","that","Ich weiß, dass er Deutsch lernt."],["weil","because","Ich bleibe, weil ich müde bin."],["wenn","when/if","Wenn ich Zeit habe, komme ich."],["ob","whether/if","Ich weiß nicht, ob er kommt."]],"headers":["Conjunction","Meaning","Example"]}'::jsonb
WHERE id = '7873978c-3331-4a52-9bb0-aa5126ddce02'::uuid
  AND content = '{"rows":[["dass","that","Ich weiß, dass er Deutsch lernt."],["weil","because","Ich bleibe, weil ich müde bin."],["wenn","when/if","Wenn ich Zeit habe, komme ich."],["obwohl","although","Obwohl es regnet, gehe ich."],["ob","whether/if","Ich weiß nicht, ob er kommt."],["als","when (past)","Als ich jung war, spielte ich viel."],["bevor","before","Bevor du gehst, ruf mich an."],["nachdem","after","Nachdem er gegessen hat, schläft er."],["während","while","Während ich arbeite, hört sie Musik."],["bis","until","Warte, bis ich fertig bin."],["seit/seitdem","since","Seitdem er hier wohnt, ist er glücklich."],["damit","so that","Ich lerne, damit ich bestehe."],["sodass","so that (result)","Er war müde, sodass er schlief."]],"headers":["Conjunction","Meaning","Example"]}'::jsonb;

UPDATE public.grammar_rules
SET content = '{"lines":[{"de":"Weißt du, ob Tom am Samstag kommt?","en":"Do you know if Tom is coming on Saturday?","speaker":"Anna","highlight":"ob Tom am Samstag kommt"},{"de":"Ich glaube, dass er arbeiten muss.","en":"I think that he has to work.","speaker":"Ben","highlight":"dass er arbeiten muss"},{"de":"Schade! Ich hoffe, dass wir alle zusammen sein können.","en":"Too bad! I hope that we can all be together.","speaker":"Anna","highlight":"dass wir alle zusammen sein können"},{"de":"Vielleicht kann er kommen, wenn er mit der Arbeit fertig ist.","en":"Maybe he can come when he is finished with work.","speaker":"Ben","highlight":"wenn er mit der Arbeit fertig ist"},{"de":"Gute Idee! Ich frage ihn, wenn ich ihn heute sehe.","en":"Good idea! I will ask him when I see him today.","speaker":"Anna","highlight":"wenn ich ihn heute sehe"},{"de":"Sag ihm, dass wir um 19 Uhr anfangen.","en":"Tell him that we start at 7 pm.","speaker":"Ben","highlight":"dass wir um 19 Uhr anfangen"}],"context_de":"Zwei Kollegen besprechen Wochenendpläne.","context_en":"Two colleagues discussing weekend plans."}'::jsonb
WHERE id = '72f85611-66e4-4a83-846e-948ed7fc7d94'::uuid
  AND content = '{"lines":[{"de":"Weißt du, ob Tom am Samstag kommt?","en":"Do you know if Tom is coming on Saturday?","speaker":"Anna","highlight":"ob Tom am Samstag kommt"},{"de":"Ich glaube, dass er arbeiten muss.","en":"I think that he has to work.","speaker":"Ben","highlight":"dass er arbeiten muss"},{"de":"Schade! Ich hatte gehofft, dass wir alle zusammen sein können.","en":"Too bad! I had hoped that we could all be together.","speaker":"Anna","highlight":"dass wir alle zusammen sein können"},{"de":"Vielleicht kann er kommen, nachdem er gearbeitet hat.","en":"Maybe he can come after he has worked.","speaker":"Ben","highlight":"nachdem er gearbeitet hat"},{"de":"Gute Idee! Ich frage ihn, wenn ich ihn heute sehe.","en":"Good idea! I will ask him when I see him today.","speaker":"Anna","highlight":"wenn ich ihn heute sehe"},{"de":"Sag ihm, dass wir um 19 Uhr anfangen, obwohl einige früher kommen.","en":"Tell him that we start at 7 pm, although some are coming earlier.","speaker":"Ben","highlight":"dass wir um 19 Uhr anfangen, obwohl einige früher kommen"}],"context_de":"Zwei Kollegen besprechen Wochenendpläne.","context_en":"Two colleagues discussing weekend plans."}'::jsonb;

UPDATE public.grammar_rules
SET content = '{"what_next_en":"Practice with common conjunctions: weil (because), dass (that), wenn (when/if). Start simple before adding modals or perfect tense.","golden_rule_de":"Nach Nebensatzkonjunktionen (dass, weil, wenn, ob) steht das konjugierte Verb am Satzende.","golden_rule_en":"After subordinating conjunctions (dass, weil, wenn, ob), the conjugated verb goes to the end of the clause.","memory_trick_de":"KONJUNKTION = Verb ans Ende. Die Konjunktion ist wie ein ''Verbmagnet''.","memory_trick_en":"CONJUNCTION = verb at the end. No exceptions! Think of the conjunction as a ''verb magnet'' that pulls the verb to the end.","quick_reference":["Simple verb → goes to end: ...dass er Deutsch lernt.","Separable verb → reunites at end: ...weil ich aufstehe.","Modal + infinitive → infinitive + modal: ...dass ich kommen kann.","Perfect tense → participle + auxiliary: ...weil ich gelesen habe.","Future tense → infinitive + werden: ...dass ich kommen werde."]}'::jsonb
WHERE id = 'c9511dce-d0a1-4931-903f-df5fc11bb003'::uuid
  AND content = '{"what_next_en":"Practice with common conjunctions: weil (because), dass (that), wenn (when/if). Start simple before adding modals or perfect tense.","golden_rule_de":"Nach Nebensatzkonjunktionen (dass, weil, wenn, ob, als, usw.) steht das konjugierte Verb am Ende des Satzes.","golden_rule_en":"After subordinating conjunctions (dass, weil, wenn, ob, als, etc.), the conjugated verb goes to the end of the clause.","memory_trick_de":"KONJUNKTION = verb ans Ende. Der Konjunktion ist wie ein ''Verbmagnet''.","memory_trick_en":"CONJUNCTION = verb at the end. No exceptions! Think of the conjunction as a ''verb magnet'' that pulls the verb to the end.","quick_reference":["Simple verb → goes to end: ...dass er Deutsch lernt.","Separable verb → reunites at end: ...weil ich aufstehe.","Modal + infinitive → infinitive + modal: ...dass ich kommen kann.","Perfect tense → participle + auxiliary: ...weil ich gelesen habe.","Future tense → infinitive + werden: ...dass ich kommen werde."]}'::jsonb;

