UPDATE public.grammar_rules
SET common_mistakes = '[{"wrong":"Ich muss zu arbeiten.","correct":"Ich muss arbeiten.","explanation_de":"Modalverben stehen immer mit bloßem Infinitiv, nie mit zu.","explanation_en":"Modal verbs always take a bare infinitive; they never take zu."},{"wrong":"Ich vergesse zu anrufen meine Mutter.","correct":"Ich vergesse, meine Mutter anzurufen.","explanation_de":"Bei trennbaren Verben kommt zu mitten ins Verb, und das Objekt steht davor.","explanation_en":"With a separable verb, zu goes inside the verb itself, and the object comes before it: meine Mutter anzurufen."},{"wrong":"Ich gehe zu schwimmen.","correct":"Ich gehe schwimmen.","explanation_de":"gehen steht mit bloßem Infinitiv, ganz ohne zu.","explanation_en":"gehen takes a bare infinitive with no zu at all."},{"wrong":"Es ist wichtig pünktlich zu sein.","correct":"Es ist wichtig, pünktlich zu sein.","explanation_de":"Nach es ist wichtig steht immer ein Komma.","explanation_en":"After es ist wichtig the comma is obligatory."},{"wrong":"Ich habe Lust, zu gehen ins Kino.","correct":"Ich habe Lust, ins Kino zu gehen.","explanation_de":"zu + Verb steht in der zu-Gruppe ganz am Ende.","explanation_en":"zu + verb goes to the very end of the zu-group."},{"wrong":"Ich habe vor, morgen ein zu kaufen.","correct":"Ich habe vor, morgen einzukaufen.","explanation_de":"einkaufen ist ein trennbares Verb; zu kommt hinein und alles bleibt ein Wort: einzukaufen.","explanation_en":"einkaufen is one separable verb; zu goes inside it and the whole thing stays one word: einzukaufen."}]'::jsonb
WHERE id = '83925329-74b0-5bae-962d-069e5b9671b0'::uuid
  AND common_mistakes = '[{"wrong":"Ich muss zu arbeiten.","correct":"Ich muss arbeiten.","explanation_de":"Modalverben stehen immer mit bloßem Infinitiv, nie mit zu.","explanation_en":"Modal verbs always take a bare infinitive; they never take zu."},{"wrong":"Ich vergesse zu anrufen meine Mutter.","correct":"Ich vergesse, meine Mutter anzurufen.","explanation_de":"Bei trennbaren Verben kommt zu mitten ins Verb, und das Objekt steht davor.","explanation_en":"With a separable verb, zu goes inside the verb itself, and the object comes before it: meine Mutter anzurufen."},{"wrong":"Ich gehe zu schwimmen.","correct":"Ich gehe schwimmen.","explanation_de":"gehen steht mit bloßem Infinitiv, ganz ohne zu.","explanation_en":"gehen takes a bare infinitive with no zu at all."},{"wrong":"Es ist wichtig pünktlich zu sein.","correct":"Es ist wichtig, pünktlich zu sein.","explanation_de":"Nach es ist wichtig steht immer ein Komma.","explanation_en":"After es ist wichtig the comma is obligatory."},{"wrong":"Ich habe Lust, zu gehen ins Kino.","correct":"Ich habe Lust, ins Kino zu gehen.","explanation_de":"zu + Verb steht ganz am Ende der zu-Gruppe.","explanation_en":"zu + verb goes to the very end of the zu-group."},{"wrong":"Ich habe vor, morgen ein zu kaufen.","correct":"Ich habe vor, morgen einzukaufen.","explanation_de":"einkaufen ist ein trennbares Verb; zu kommt hinein und alles bleibt ein Wort: einzukaufen.","explanation_en":"einkaufen is one separable verb; zu goes inside it and the whole thing stays one word: einzukaufen."}]'::jsonb;

