UPDATE public.grammar_rules
SET content = '{"hook_de":"Im Hauptsatz steht das Verb an Position 2. Aber im Nebensatz? Das Verb geht ans Ende!","hook_en":"In German main clauses, the verb is in position 2. But in subordinate clauses? The verb gets kicked to the end! ''Ich weiß, dass er Deutsch lernt'' — the conjugated verb ''lernt'' waits at the very end. This is one of the most distinctive features of German.","scenario_en":"Explaining reasons: ''Ich bleibe zu Hause, weil ich krank bin.'' Expressing opinions: ''Ich denke, dass das richtig ist.'' Describing conditions: ''Wenn ich Zeit habe, komme ich.''","preview_note_en":"Notice: ''lernt'' moves from position 2 (main clause) to the end (subordinate clause).","preview_highlight":"dass er jeden Tag Deutsch lernt","why_it_matters_en":"Every time you use weil, dass, wenn, or ob, you must send the verb to the end. This is non-negotiable in German.","preview_example_de":"Ich weiß, dass er jeden Tag Deutsch lernt.","preview_example_en":"I know that he learns German every day.","german_difference_en":"German subordinate clauses require the conjugated verb at the end. This creates a ''verb bracket'' structure that feels backward to English speakers, but it''s completely logical once you understand it.","difficulty_warning_en":"The hardest part: when you have multiple verbs (modal + infinitive, or perfect tense), they all pile up at the end in a specific order.","english_comparison_en":"English keeps normal word order in subordinate clauses: ''I know that he learns German'' — ''learns'' stays in the middle. German sends it to the end!"}'::jsonb
WHERE id = '15c6658c-98fc-4b57-a8a3-0cce85a66b3a'::uuid
  AND content = '{"hook_de":"Im Hauptsatz steht das Verb an Position 2. Aber im Nebensatz? Das Verb geht ans Ende!","hook_en":"In German main clauses, the verb is in position 2. But in subordinate clauses? The verb gets kicked to the end! ''Ich weiß, dass er Deutsch lernt'' — the conjugated verb ''lernt'' waits at the very end. This is one of the most distinctive features of German.","scenario_en":"Explaining reasons: ''Ich bleibe zu Hause, weil ich krank bin.'' Expressing opinions: ''Ich denke, dass das richtig ist.'' Describing conditions: ''Wenn ich Zeit habe, komme ich.''","preview_note_en":"Notice: ''lernt'' moves from position 2 (main clause) to the end (subordinate clause).","preview_highlight":"dass er jeden Tag Deutsch lernt","why_it_matters_en":"Every time you use weil, dass, wenn, obwohl, or any other subordinating conjunction, you must send the verb to the end. This is non-negotiable in German.","preview_example_de":"Ich weiß, dass er jeden Tag Deutsch lernt.","preview_example_en":"I know that he learns German every day.","german_difference_en":"German subordinate clauses require the conjugated verb at the end. This creates a ''verb bracket'' structure that feels backward to English speakers, but it''s completely logical once you understand it.","difficulty_warning_en":"The hardest part: when you have multiple verbs (modal + infinitive, or perfect tense), they all pile up at the end in a specific order.","english_comparison_en":"English keeps normal word order in subordinate clauses: ''I know that he learns German'' — ''learns'' stays in the middle. German sends it to the end!"}'::jsonb;

UPDATE public.grammar_rules
SET content = '{"mistakes":[{"wrong":"Ich weiß, dass er lernt Deutsch.","correct":"Ich weiß, dass er Deutsch lernt.","explanation_de":"Das Verb muss ans Ende, nicht an Position 2!","explanation_en":"Verb must go to the end, not stay in position 2!"},{"wrong":"..., weil ich kann nicht kommen.","correct":"..., weil ich nicht kommen kann.","explanation_de":"Mit Modalverben: Infinitiv + Modal am Ende. ''kann'' geht zuletzt!","explanation_en":"With modals: infinitive + modal at the end. ''kann'' goes last!"},{"wrong":"..., dass ich habe das Buch gelesen.","correct":"..., dass ich das Buch gelesen habe.","explanation_de":"Perfekt: Partizip + Hilfsverb am Ende. ''habe'' geht zuletzt!","explanation_en":"Perfect tense: participle + auxiliary at the end. ''habe'' goes last!"},{"wrong":"..., weil ich auf um 7 Uhr stehe.","correct":"..., weil ich um 7 Uhr aufstehe.","explanation_de":"Trennbare Verben vereinigen sich im Nebensatz wieder!","explanation_en":"Separable verbs reunite in subordinate clauses. Write as one word!"},{"wrong":"Wenn ich habe Zeit, komme ich.","correct":"Wenn ich Zeit habe, komme ich.","explanation_de":"''habe'' muss im wenn-Satz ans Ende!","explanation_en":"''habe'' must go to the end of the wenn-clause!"},{"wrong":"Er sagt, dass er geht morgen.","correct":"Er sagt, dass er morgen geht.","explanation_de":"Zeitangaben kommen vor dem Verb am Ende.","explanation_en":"Time expressions come before the verb at the end."}]}'::jsonb
WHERE id = '46e0a30a-13f3-4d50-a09b-87ede5461e30'::uuid
  AND content = '{"mistakes":[{"wrong":"Ich weiß, dass er lernt Deutsch.","correct":"Ich weiß, dass er Deutsch lernt.","explanation_de":"Das Verb muss ans Ende, nicht an Position 2!","explanation_en":"Verb must go to the end, not stay in position 2!"},{"wrong":"..., weil ich kann nicht kommen.","correct":"..., weil ich nicht kommen kann.","explanation_de":"Mit Modalverben: Infinitiv + Modal am Ende. ''kann'' geht zuletzt!","explanation_en":"With modals: infinitive + modal at the end. ''kann'' goes last!"},{"wrong":"..., dass ich habe das Buch gelesen.","correct":"..., dass ich das Buch gelesen habe.","explanation_de":"Perfekt: Partizip + Hilfsverb am Ende. ''habe'' geht zuletzt!","explanation_en":"Perfect tense: participle + auxiliary at the end. ''habe'' goes last!"},{"wrong":"..., weil ich auf um 7 Uhr stehe.","correct":"..., weil ich um 7 Uhr aufstehe.","explanation_de":"Trennbare Verben vereinigen sich im Nebensatz wieder!","explanation_en":"Separable verbs reunite in subordinate clauses. Write as one word!"},{"wrong":"Wenn ich habe Zeit, komme ich.","correct":"Wenn ich Zeit habe, komme ich.","explanation_de":"''habe'' muss ans Ende des wenn-Satzes!","explanation_en":"''habe'' must go to the end of the wenn-clause!"},{"wrong":"Er sagt, dass er geht morgen.","correct":"Er sagt, dass er morgen geht.","explanation_de":"Zeitangaben kommen vor dem Verb am Ende.","explanation_en":"Time expressions come before the verb at the end."}]}'::jsonb;

